import { useTheme } from '@emotion/react';

import { Typography } from '@mui/material';

import GameFlag from 'components/ui/GameFlag';
import { TYPE_COUNTRY } from 'components/wiki/Wiki';
import { pxToRem } from 'util/util';

export const CountryLabelWithFlag = (props) => {
    const { country, onClickCountry, language } = props;
    const theme = useTheme();

    return (
        <Typography
            component="a"
            display="inline-block"
            fontSize={pxToRem(14)}
            lineHeight={pxToRem(18)}
            onClick={() => {
                onClickCountry?.(country, TYPE_COUNTRY);
            }}
            key={country.cca3}
            sx={{
                background: 'transparent',
                color: theme.palette.text.main,
                border: 'none',
                padding: 0,
                textDecoration: 'underline',
                textAlign: 'left',
                pr: '24px',
                cursor: onClickCountry ? 'pointer' : 'initial',
                '&:hover': {
                    color: theme.palette.primary.main,
                },
            }}>
            {country.getName(language)}&nbsp;
            <GameFlag
                country={country.cca3}
                svgOverrides={{
                    maxWidth: pxToRem(20),
                    maxHeight: 'none',
                    width: 'auto',
                    height: pxToRem(16),
                    verticalAlign: 'middle',
                    position: 'absolute',
                }}
            />
        </Typography>
    );
};
