import { useTheme } from '@emotion/react';

import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import ArrowForwardIosIcon from '@mui/icons-material/ArrowForwardIos';
import { Box, Card, IconButton, Table, TableCell, TableRow, Typography } from '@mui/material';

import { pxToRem } from 'util/util';

const WikiCard = (props) => {
    return (
        <Card
            sx={{
                px: 2,
                py: 2,
                mt: 2,
                textAlign: 'center',
                width: '100%',
                height: '100%',
                // boxSizing: 'border-box',
                position: 'relative',
                display: 'flex',
                flexFlow: 'column',
                flexGrow: 1,
                '& > div': {
                    mt: pxToRem(16),
                },
                '& > div:first-of-type': {
                    mt: 0,
                },
            }}>
            {props.children}
        </Card>
    );
};

export const CardTitle = (props) => {
    const { onPrevious, onNext, title, sxOverride } = props;
    return (
        <Box
            sx={{
                position: 'relative',
                ...sxOverride,
            }}>
            {onPrevious && (
                <IconButton
                    className="standalone"
                    onClick={onPrevious}
                    size="small"
                    sx={{
                        position: 'absolute',
                        left: 0,
                        top: pxToRem(-8),
                        height: pxToRem(37),
                    }}>
                    <ArrowBackIosNewIcon />
                </IconButton>
            )}
            <Typography fontSize={pxToRem(20)} fontWeight="700" lineHeight={pxToRem(21)} mx={pxToRem(36)}>
                {title}
            </Typography>
            {onNext && (
                <IconButton
                    className="standalone"
                    onClick={onNext}
                    size="small"
                    sx={{
                        position: 'absolute',
                        right: 0,
                        top: pxToRem(-8),
                        height: pxToRem(37),
                    }}>
                    <ArrowForwardIosIcon />
                </IconButton>
            )}
        </Box>
    );
};

export const CardTable = (props) => {
    const { aria, rows } = props;
    const theme = useTheme();
    return (
        <Box
            display="flex"
            flex="1 1 auto"
            sx={{
                position: 'relative',
                overflow: 'auto',
                // boxShadow: 5,
                border: 1,
                borderColor: theme.palette.neutral[200],
                borderRadius: pxToRem(8),
            }}>
            <Table
                size="small"
                sx={{
                    fontSize: pxToRem(11),
                    lineHeight: pxToRem(12),
                    position: 'absolute',
                    top: 0,
                    bottom: 0,
                    left: 0,
                    right: 0,
                }}
                aria-label={`${aria}`}>
                <tbody>
                    {rows.map((r) => (
                        <Row key={r.label}>
                            <CellProp>
                                <TypographyTable>{r.label}</TypographyTable>
                            </CellProp>
                            <CellValue>
                                <TypographyTable>{r.value}</TypographyTable>
                            </CellValue>
                        </Row>
                    ))}
                </tbody>
            </Table>
        </Box>
    );
};

export const Row = (props) => {
    const theme = useTheme();
    return (
        <TableRow
            {...props}
            sx={{
                // border: 0,
                '&:first-of-type td': {
                    pt: pxToRem(10),
                },
                '&:last-child td': {
                    pb: pxToRem(10),
                },
                '&:nth-of-type(even) td': {
                    backgroundColor: theme.palette.background.tableRow,
                },
            }}>
            {props.children}
        </TableRow>
    );
};

export const CellProp = (props) => {
    return (
        <TableCell
            {...props}
            sx={{
                color: (theme) => theme.palette.text.secondary,
                px: pxToRem(10),
                verticalAlign: 'baseline',
                width: pxToRem(130),
                border: 0,
            }}>
            {props.children}
        </TableCell>
    );
};

export const CellValue = (props) => {
    return (
        <TableCell
            {...props}
            sx={{
                paddingLeft: pxToRem(10),
                verticalAlign: 'baseline',
                border: 0,
            }}>
            {props.children}
        </TableCell>
    );
};

export const TypographyTable = (props) => {
    return (
        <Typography
            {...props}
            sx={{
                fontSize: pxToRem(14),
                lineHeight: pxToRem(16),
                verticalAlign: 'middle',
            }}>
            {props.children}
        </Typography>
    );
};

export default WikiCard;
