import { useTheme } from '@emotion/react';
import * as React from 'react';
import { useTranslation } from 'react-i18next';

import { Box, Card } from '@mui/material';

import GameFlag from 'components/ui/GameFlag';
import Map, { TILE_LIGHT_ALL } from 'components/ui/Map';
import { CountryLabelWithFlag } from 'components/wiki/CountryLabelWithFlag';
import WikiCard, { CardTable, CardTitle } from 'components/wiki/WikiCard';
import { getCountries } from 'data/data';
import { pxToRem } from 'util/util';

const CountryCard = (props) => {
    const { country, onNext, onPrevious, onClickCountry } = props;
    const { i18n, t } = useTranslation();
    const theme = useTheme();
    const countries = getCountries();

    if (!country) {
        return null;
    }

    const region = country.region?.getName(i18n.language);
    const subregion = country.subregion?.getName(i18n.language);

    const hasSovereignState = !country.independent && country.sovereignState;
    const sovereignStateCountry = hasSovereignState ? countries[country.sovereignState] : undefined;

    const borders =
        country.borders && country.borders.length
            ? country.borders.map((border, index) => {
                  const cBorder = countries[border];

                  return (
                      <CountryLabelWithFlag
                          key={border}
                          country={cBorder}
                          onClickCountry={onClickCountry}
                          language={i18n.language}
                      />
                  );
              })
            : '';
    const languages = country.languages ? Object.values(country.languages).join(', ') : '';
    const currencies = country.currencies
        ? Object.keys(country.currencies)
              .map((key) => country.currencies[key].name)
              .join(', ')
        : '';

    const cardTableRows = [
        {
            label: t('Official Name'),
            value: country.getOfficialName(i18n.language),
        },
        {
            label: t('ISO codes'),
            value: `${country.cca2}, ${country.cca3}`,
        },
        {
            label: t('Status'),
            value: country.independent ? t('independent') : t('dependent'),
        },
        ...(hasSovereignState
            ? [
                  {
                      label: t('Sovereign State'),
                      value: (
                          <CountryLabelWithFlag
                              country={sovereignStateCountry}
                              onClickCountry={onClickCountry}
                              language={i18n.language}
                          />
                      ),
                  },
              ]
            : []),
        {
            label: t('Capital'),
            value: country?.capital?.map((cap) => cap.name[i18n.language]).join(', '),
        },
        {
            label: t('Other Cities'),
            value: country?.cities?.map((city) => city.name[i18n.language]).join(', '),
        },
        {
            label: t('Region'),
            value: `${region}${subregion ? `, ${subregion}` : ''}`,
        },
        {
            label: t('Borders'),
            value: borders,
        },
        {
            label: t('Languages'),
            value: languages,
        },
        {
            label: t('Currencies'),
            value: currencies,
        },
    ];

    const markers = [
        ...country?.capital?.map((c) => c.coordinates),
        // ...country?.cities?.map((c) => c.coordinates),
    ].filter((c) => !!c);

    return (
        <WikiCard>
            <CardTitle title={country.getName(i18n.language)} onPrevious={onPrevious} onNext={onNext} />
            <Box
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                }}>
                <GameFlag
                    country={country.cca3}
                    svgOverrides={{
                        filter: 'drop-shadow(0px 4px 4px rgba(0, 0, 0, 0.3))',
                        maxHeight: '9vh',
                    }}
                />
            </Box>
            <Card
                sx={{
                    padding: 0,
                    border: 1,
                    borderColor: theme.palette.neutral[200],
                    borderRadius: pxToRem(8),
                }}>
                <Map
                    tileProviderKey={TILE_LIGHT_ALL}
                    markers={markers}
                    geoFileName={country.cca3.toLowerCase()}
                    geoFolder="geo"
                    initialMapHeight="24vh"
                    useFullScreen={!!onNext}
                />
            </Card>
            <CardTable aria={`Country ${country.getName(i18n.language)}`} rows={cardTableRows} />
        </WikiCard>
    );
};

export default CountryCard;
