import { CAT_PEAK } from 'config/baseConfig';
import * as React from 'react';
import { useTranslation } from 'react-i18next';

import OpenInNewIcon from '@mui/icons-material/OpenInNew';
import { Box, Link } from '@mui/material';

import GamePicture from 'components/ui/GamePicture';
import NoPicture from 'components/ui/NoPicture';
import { CountryLabelWithFlag } from 'components/wiki/CountryLabelWithFlag';
import WikiCard, { CardTable, CardTitle } from 'components/wiki/WikiCard';

const PeakCard = (props) => {
    const { peak, onNext, onPrevious, onClickCountry } = props;
    const { i18n, t } = useTranslation();

    if (!peak) {
        return null;
    }

    const countries =
        peak.country && peak.country.length
            ? peak.country.map((c, index) => {
                  return (
                      <CountryLabelWithFlag
                          key={c.cca3}
                          country={c}
                          onClickCountry={onClickCountry}
                          language={i18n.language}
                      />
                  );
              })
            : '';

    const cardTableRows = [
        {
            label: t('Other Names'),
            value: peak.altername_names,
        },
        {
            label: t('Range or Island'),
            value: peak.range_or_island,
        },
        {
            label: t('Elevation'),
            value: (
                <>
                    {peak.elevation} <small>{t('meters')}</small>
                </>
            ),
        },
        {
            label: t('Prominence'),
            value: (
                <>
                    {peak.prominence} <small>{t('meters')}</small>
                </>
            ),
        },
        {
            label: t('Country'),
            value: countries,
        },
        {
            label: t('Region'),
            value: peak.getRegion(i18n.language),
        },
        {
            label: t('Coordinates'),
            value: (
                <Link href={`https://www.google.ca/maps/place/${peak.coord}`} target="_blank">
                    {peak.coord}
                    &nbsp;
                    <OpenInNewIcon size="small" sx={{ verticalAlign: 'middle', width: '0.75em', height: '0.75em' }} />
                </Link>
            ),
        },
    ];

    return (
        <WikiCard>
            <CardTitle title={peak.getName(i18n.language)} onPrevious={onPrevious} onNext={onNext} />
            <Box
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    height: '25vh',
                }}>
                {peak.images && peak.images.length > 0 ? (
                    <GamePicture
                        image={peak.images[0]} // Math.floor(Math.random()*peak.images.length)
                        images={peak.images} // Math.floor(Math.random()*peak.images.length)
                        altText={peak.getName()}
                        overrideSx={{
                            height: 'auto',
                            maxHeight: '25vh',
                            width: 'auto',
                        }}
                    />
                ) : (
                    <NoPicture icon={CAT_PEAK} />
                )}
            </Box>
            <CardTable aria={`Peak ${peak.getName(i18n.language)}`} rows={cardTableRows} />
        </WikiCard>
    );
};

export default PeakCard;
