import { useTheme } from '@emotion/react';
import * as React from 'react';
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch } from 'react-redux';

import ArrowCircleLeftIcon from '@mui/icons-material/ArrowCircleLeft';
import ArrowCircleRightIcon from '@mui/icons-material/ArrowCircleRight';
import CloudOffIcon from '@mui/icons-material/CloudOff';
import { Box, IconButton, Link, Modal } from '@mui/material';

import ConfirmDialog from 'components/ui/ConfirmDialog';
import { gameAnswer } from 'store/actions';
import { pxToRem } from 'util/util';

const GamePicture = (props) => {
    const { image, images, altText, inGame, phase } = props;
    const theme = useTheme();
    const dispatch = useDispatch();
    const { t } = useTranslation();

    const [displayedImage, setDisplayedImage] = useState(image || images[0]);
    const [displayedIndex, setDisplayedIndex] = useState(0);
    const [open, setOpen] = useState(false);
    const [creditsDisplayed, setCreditsDisplayed] = useState(false);
    const [confirmDisplayCreditsOpen, setConfirmDisplayCreditsOpen] = useState(false);

    useEffect(() => {
        setCreditsDisplayed(false);
        setDisplayedIndex(0);
        setDisplayedImage(image || images[0]);
    }, [image, images]);

    useEffect(() => {
        if (phase === 2) {
            setCreditsDisplayed(true);
        }
    }, [phase]);

    useEffect(() => {
        if (images) {
            setDisplayedImage(images[displayedIndex]);
        }
    }, [displayedIndex]);

    if (!displayedImage?.src) {
        return null;
    }

    const onClickImg = () => {
        setOpen(true);
    };
    const onCloseImg = () => {
        setOpen(false);
    };
    const onClickSeeCredits = () => {
        setConfirmDisplayCreditsOpen(true);
    };
    const handleConfirmDisplayCredits = () => {
        setCreditsDisplayed(true);
        setConfirmDisplayCreditsOpen(false);
        dispatch(gameAnswer(''));
    };
    const handleConfirmContinue = () => {
        setConfirmDisplayCreditsOpen(false);
    };

    const onPrevious = () => {
        setDisplayedIndex(displayedIndex - 1);
    };
    const onNext = () => {
        setDisplayedIndex(displayedIndex + 1);
    };

    if (!navigator.onLine) {
        return (
            <Box
                component="span"
                sx={{
                    height: '160px',
                    width: '240px',
                    display: 'flex',
                    justifyContent: 'center',
                    alignItems: 'center',
                    border: `solid 2px ${theme.palette.secondary.alpha30}`,
                    backgroundColor: theme.palette.primary.alpha8,
                    svg: {
                        color: theme.palette.secondary.alpha30,
                        height: pxToRem(96),
                        width: pxToRem(96),
                        fill: 'currentColor',
                    },
                }}>
                <CloudOffIcon />
            </Box>
        );
    }

    return (
        <Box display="inline-block" position="relative">
            <Box
                component="img"
                src={displayedImage.src}
                alt={altText}
                onClick={onClickImg}
                sx={{
                    height: 'auto',
                    maxHeight: '25vh',
                    width: 'auto',
                    maxWidth: '100%',
                    verticalAlign: 'middle',
                    cursor: 'zoom-in',
                    ...props.overrideSx,
                }}
            />
            {inGame ? (
                <>
                    <Box
                        dangerouslySetInnerHTML={creditsDisplayed ? { __html: displayedImage.attribution } : null}
                        sx={{
                            bgcolor: 'rgba(0,0,0,0.75)',
                            position: 'absolute',
                            bottom: 0,
                            fontSize: pxToRem(10),
                            textAlign: 'left',
                            color: theme.palette.text.attribution,
                            padding: `${pxToRem(2)} ${pxToRem(4)}`,
                            'a, button': {
                                fontSize: pxToRem(10),
                                color: theme.palette.text.attribution,
                                textDecorationColor: theme.palette.text.attribution,
                            },
                        }}>
                        {!creditsDisplayed ? (
                            <Link component="button" onClick={onClickSeeCredits}>
                                {t('Display Credit')}
                            </Link>
                        ) : null}
                    </Box>
                    <ConfirmDialog
                        open={confirmDisplayCreditsOpen}
                        title={t('Display Credit?')}
                        text={t('Display Credit Text')}
                        leftHandler={handleConfirmDisplayCredits}
                        leftLabel={t('Display')}
                        rightHandler={handleConfirmContinue}
                        rightLabel={t('Wait')}
                    />
                </>
            ) : (
                <>
                    <Box
                        dangerouslySetInnerHTML={{ __html: displayedImage.attribution }}
                        sx={{
                            bgcolor: 'rgba(0,0,0,0.75)',
                            position: 'absolute',
                            bottom: 0,
                            fontSize: pxToRem(10),
                            textAlign: 'left',
                            color: theme.palette.text.attribution,
                            padding: `${pxToRem(2)} ${pxToRem(4)}`,
                            a: {
                                color: theme.palette.text.attribution,
                            },
                        }}></Box>
                    {images?.length > 1 && (
                        <>
                            <IconButton
                                className="standalone"
                                onClick={onPrevious}
                                disabled={displayedIndex === 0}
                                size="medium"
                                sx={{
                                    position: 'absolute',
                                    left: pxToRem(3),
                                    top: 0,
                                    height: pxToRem(37),
                                    opacity: displayedIndex === 0 ? 0.5 : 1,
                                    svg: {
                                        fill: '#fff',
                                    },
                                }}>
                                <ArrowCircleLeftIcon />
                            </IconButton>
                            <IconButton
                                className="standalone"
                                onClick={onNext}
                                disabled={displayedIndex === images.length - 1}
                                size="medium"
                                sx={{
                                    position: 'absolute',
                                    right: pxToRem(3),
                                    top: 0,
                                    height: pxToRem(37),
                                    opacity: displayedIndex === images.length - 1 ? 0.5 : 1,
                                    svg: {
                                        fill: '#fff',
                                    },
                                }}>
                                <ArrowCircleRightIcon />
                            </IconButton>
                        </>
                    )}
                </>
            )}
            <Modal
                open={open}
                onClose={onCloseImg}
                aria-labelledby="modal-modal-title"
                aria-describedby="modal-modal-description">
                <Box
                    sx={{
                        bgcolor: 'background.paper',
                        border: '2px solid #000',
                        position: 'relative',
                    }}>
                    <img
                        src={displayedImage.src}
                        alt={altText}
                        onClick={onCloseImg}
                        style={{
                            display: 'block',
                            height: 'auto',
                            width: 'auto',
                            maxWidth: '100%',
                            maxHeight: 'calc(100vh - 0px)',
                        }}
                    />
                    {/*<IconButton className='standalone'
                        // aria-label={t('Close')}
                        onClick={onCloseImg}
                        color="primary.contrast"
                        sx={{
                            backgroundColor: 'black',
                            position: 'absolute',
                            right: pxToRem(16),
                            top: pxToRem(16),
                        }}
                    >
                        <CloseIcon />
                    </IconButton>*/}
                </Box>
            </Modal>
        </Box>
    );
};

export default GamePicture;
