import * as React from 'react';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Autocomplete, Box, Tab, Tabs, TextField, Typography } from '@mui/material';

import GameFlag from 'components/ui/GameFlag';
import CountryCard from 'components/wiki/CountryCard';
import LandmarkCard from 'components/wiki/LandmarkCard';
import PeakCard from 'components/wiki/PeakCard';
import SeaCard from 'components/wiki/SeaCard';
import { getCountries, getLandmarks, getPeaks, getSeasAndLakes } from 'data/data';
import { pxToRem } from 'util/util';

export const TYPE_COUNTRY = 0;
export const TYPE_PEAK = 1;
export const TYPE_LANDMARK = 2;
export const TYPE_SEA = 3;

const Wiki = (props) => {
    const { i18n, t } = useTranslation();
    const countriesData = Object.values(getCountries());
    const peaksData = getPeaks();
    const landmarksData = getLandmarks();
    const seasData = Object.values(getSeasAndLakes());

    const [country, setCountry] = useState(countriesData[0]);
    const [peak, setPeak] = useState(peaksData[0]);
    const [landmark, setLandmark] = useState(landmarksData[0]);
    const [sea, setSea] = useState(seasData[0]);
    const [currentType, setCurrentType] = useState(0);
    const [entity, setEntity] = useState(undefined);
    const [entities, setEntities] = useState(countriesData);

    const doSetEntity = (_entity, _type) => {
        const type = typeof _type !== 'undefined' ? _type : currentType;
        setEntity(_entity);
        switch (type) {
            case TYPE_SEA:
                setSea(_entity);
                setEntities(seasData);
                break;
            case TYPE_LANDMARK:
                setLandmark(_entity);
                setEntities(landmarksData);
                break;
            case TYPE_PEAK:
                setPeak(_entity);
                setEntities(peaksData);
                break;
            case TYPE_COUNTRY:
            default:
                setCountry(_entity);
                setEntities(countriesData);
                break;
        }
    };

    const handleChangeEntity = (event, newEntity) => {
        doSetEntity(newEntity, currentType);
    };
    const handleClickPrevious = () => {
        const currEntity = getCurrentEntity();
        const entities = getEntities();
        const currIndex = entities.indexOf(currEntity);
        const newIndex = currIndex - 1 < 0 ? entities.length - 1 : currIndex - 1;
        doSetEntity(entities[newIndex]);
    };
    const handleClickNext = () => {
        const currEntity = getCurrentEntity();
        const entities = getEntities();
        const currIndex = entities.indexOf(currEntity);
        const newIndex = currIndex + 1 >= entities.length ? 0 : currIndex + 1;
        doSetEntity(entities[newIndex]);
    };

    const handleClickEntity = (entity, type) => {
        if (type !== currentType) {
            setCurrentType(type);
        }
        doSetEntity(entity, type);
    };
    const handleChangeCurrentType = (event, newType) => {
        setCurrentType(newType);
        switch (newType) {
            case TYPE_SEA:
                setEntity(sea);
                setEntities(seasData);
                break;
            case TYPE_LANDMARK:
                setEntity(landmark);
                setEntities(landmarksData);
                break;
            case TYPE_PEAK:
                setEntity(peak);
                setEntities(peaksData);
                break;
            case TYPE_COUNTRY:
            default:
                setEntity(country);
                setEntities(countriesData);
                break;
        }
    };
    const getEntities = (_type) => {
        const type = typeof _type !== 'undefined' ? _type : currentType;
        switch (type) {
            // OTHER TYPES EVENTUALLY
            case TYPE_LANDMARK:
                return landmarksData;
            case TYPE_SEA:
                return seasData;
            case TYPE_PEAK:
                return peaksData;
            case TYPE_COUNTRY:
            default:
                return countriesData;
        }
    };
    const getCurrentEntity = (_type) => {
        const type = typeof _type !== 'undefined' ? _type : currentType;
        switch (type) {
            // OTHER TYPES EVENTUALLY
            case TYPE_SEA:
                return sea;
            case TYPE_LANDMARK:
                return landmark;
            case TYPE_PEAK:
                return peak;
            case TYPE_COUNTRY:
            default:
                return country;
        }
    };

    return (
        <>
            <Box
                display="flex"
                flex="0 1 auto"
                alignItems="center"
                flexDirection="column"
                justifyContent="flex-start"
                width="100%"
                height="100%"
                flexGrow={1}
                position="relative">
                <Tabs value={currentType} onChange={handleChangeCurrentType} aria-label="Sections">
                    <Tab label={t('Countries')} value={TYPE_COUNTRY} />
                    <Tab label={t('Peaks')} value={TYPE_PEAK} />
                    <Tab label={t('Landmarks')} value={TYPE_LANDMARK} />
                    <Tab label={t('Seas & Lakes')} value={TYPE_SEA} />
                </Tabs>
                <Autocomplete
                    id="select"
                    size="small"
                    sx={{ width: pxToRem(300), mt: 2 }}
                    options={entities}
                    blurOnSelect
                    getOptionLabel={(option) => {
                        return option?.getName(i18n.language);
                    }}
                    renderOption={(props, option) => {
                        const { key, ...restProp } = props;
                        return (
                            <Box component="li" {...restProp} key={option.key}>
                                {currentType === TYPE_COUNTRY && (
                                    <Box display="block" flexShrink={0} width={pxToRem(36)}>
                                        <GameFlag
                                            country={option.cca3}
                                            svgOverrides={{
                                                width: '100%',
                                                filter: 'drop-shadow(0px 1px 2px rgba(0, 0, 0, 0.3))',
                                            }}
                                        />
                                    </Box>
                                )}
                                <Typography component="span" lineHeight={pxToRem(20)} flexShrink={1}>
                                    {option?.getName(i18n.language)}
                                </Typography>
                            </Box>
                        );
                    }}
                    renderInput={(params) => (
                        <TextField
                            {...params}
                            aria-label={t('Choose from the list')}
                            inputProps={{
                                ...params.inputProps,
                            }}
                        />
                    )}
                    value={entity ?? null}
                    onChange={handleChangeEntity}
                />
                {currentType === TYPE_COUNTRY ? (
                    <CountryCard
                        country={country}
                        onNext={handleClickNext}
                        onClickCountry={handleClickEntity}
                        onPrevious={handleClickPrevious}
                    />
                ) : currentType === TYPE_PEAK ? (
                    <PeakCard
                        peak={peak}
                        onNext={handleClickNext}
                        onClickCountry={handleClickEntity}
                        onPrevious={handleClickPrevious}
                    />
                ) : currentType === TYPE_LANDMARK ? (
                    <LandmarkCard
                        landmark={landmark}
                        onNext={handleClickNext}
                        onClickCountry={handleClickEntity}
                        onPrevious={handleClickPrevious}
                    />
                ) : currentType === TYPE_SEA ? (
                    <SeaCard
                        sea={sea}
                        onNext={handleClickNext}
                        onClickCountry={handleClickEntity}
                        onPrevious={handleClickPrevious}
                    />
                ) : null}
            </Box>
        </>
    );
};

export default Wiki;
