import { useTheme } from '@emotion/react';
import { booleanContains, buffer } from '@turf/turf';
import locationMarker from 'assets/images/location.svg';
import geojsonBbox from 'geojson-bbox';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import * as React from 'react';
import { useEffect, useState } from 'react';
import { GeoJSON, MapContainer, Marker, TileLayer, useMapEvents } from 'react-leaflet';

import CloseFullscreenIcon from '@mui/icons-material/CloseFullscreen';
import OpenInFullIcon from '@mui/icons-material/OpenInFull';
import { IconButton } from '@mui/material';
import { Box } from '@mui/system';

import { useIsDarkMode } from 'store/selector';
import { parseCoordinates, pxToRem } from 'util/util';

export const TILE_SATELLITE = 'satellite';
export const TILE_LIGHT_NO_LABELS = 'light_nolabels';
export const TILE_LIGHT_ALL = 'light_all';

const tileProviders = {
    light_nolabels: {
        url: 'https://{s}.basemaps.cartocdn.com/light_nolabels/{z}/{x}/{y}{r}.png',
        attribution:
            '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
    },
    light_all: {
        url: 'https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',
        attribution:
            '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
    },
    satellite: {
        url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
        attribution:
            'Tiles &copy; Esri &mdash; Source: Esri, i-cubed, USDA, USGS, AEX, GeoEye, Getmapping, Aerogrid, IGN, IGP, UPR-EGP, and the GIS User Community',
    },
};

const Map = (props) => {
    const {
        tileProviderKey,
        geoFileName,
        geoFolder,
        initialMapHeight,
        markers,
        useFullScreen,
        useClickMarker,
        onMarkerSet,
        markerResult,
        useBorderLines,
        maxZoom,
    } = props;
    const theme = useTheme();
    const isDarkMode = useIsDarkMode();
    const [mapRef, setMapRef] = useState(undefined);
    const [markersCoordinates, setMarkersCoordinates] = useState(undefined);
    const [mapHeight, setMapHeight] = useState(initialMapHeight);
    const [isFullScreen, setIsFullScreen] = useState(false);
    const [isMarkerRight, setIsMarkerRight] = useState(false);
    const [boxCss, setBoxCss] = useState({});
    const [icon, setIcon] = useState(undefined);

    const center = [0, 0];
    const setColor = ({ properties }) => {
        return { weight: 2, color: isMarkerRight ? theme.palette.success.main : theme.palette.primary.main };
    };

    // With loaded json files -->
    const [entityJson, setEntityJson] = useState(undefined);
    const [linesJson, setLinesJson] = useState(undefined);
    const [hash, setHash] = useState(undefined);
    const [extent, setExtent] = useState(undefined);

    useEffect(() => {
        if (geoFolder && geoFileName) {
            setEntityJson(undefined);
            const jsonPath = `${process.env.PUBLIC_URL}/assets/flagsAndGeo/${geoFolder}/${geoFileName}.geo.json`;
            fetch(`${jsonPath}`)
                .then((response) => {
                    if (!response.ok) {
                        throw new Error('Network response was not ok');
                    }
                    return response.json();
                })
                .then((jsonData) => {
                    // console.log(jsonData); // it correctly prints json file.
                    setHash(geoFileName);
                    setEntityJson(jsonData);
                    setExtent(geojsonBbox(jsonData));
                })
                .catch((err) => {
                    // console.log('ERR:', err, err.name, err.message);
                });
        }
    }, [geoFolder, geoFileName]);

    useEffect(() => {
        if (useBorderLines) {
            setLinesJson(undefined);
            const jsonPath = `${process.env.PUBLIC_URL}/assets/flagsAndGeo/geo/adm0boundary.geo.json`;
            fetch(`${jsonPath}`)
                .then((response) => {
                    if (!response.ok) {
                        throw new Error('Network response was not ok');
                    }
                    return response.json();
                })
                .then((jsonData) => {
                    // console.log(jsonData); // it correctly prints json file.
                    setLinesJson(jsonData);
                })
                .catch((err) => {
                    // console.log('ERR:', err, err.name, err.message);
                });
        }
    }, [useBorderLines]);

    useEffect(() => {
        // console.log(markers);
        if (markers && markers.length) {
            const coords = markers.map((m) => parseCoordinates(m));
            setMarkersCoordinates(coords);
        } else {
            setMarkersCoordinates(undefined);
        }
    }, [markers]);

    useEffect(() => {
        const markerSize = useClickMarker ? 32 : 24;
        const _icon = new L.Icon({
            iconUrl: locationMarker,
            iconAnchor: new L.Point(useClickMarker ? 16 : 12, useClickMarker ? 28 : 20),
            popupAnchor: null,
            shadowUrl: null,
            shadowSize: null,
            shadowAnchor: undefined,
            iconSize: new L.Point(markerSize, markerSize),
            className:
                markerResult === 'success'
                    ? 'iconTertiary'
                    : markerResult === 'error'
                      ? 'iconError'
                      : isDarkMode
                        ? 'iconDarkMode'
                        : 'iconLightMode',
        });
        setIcon(_icon);
    }, [useClickMarker, isDarkMode, markerResult]);

    useEffect(() => {
        mapRef?.invalidateSize();
    }, [isFullScreen]);

    if (geoFolder && geoFileName && !entityJson) {
        return null;
    }

    const handleFeature = (feature, layer) => {
        // console.log("handleFeature feature", feature);
        // console.log("handleFeature layer", layer);

        let newExtent = extent;
        if (useClickMarker && markerResult !== '' && markersCoordinates) {
            const newEntityJson = { ...entityJson };
            if (newEntityJson.features[0].geometry.type === 'MultiPolygon') {
                newEntityJson.features[0].geometry.coordinates[0][0].push([
                    markersCoordinates[0][1],
                    markersCoordinates[0][0],
                ]);
            } else {
                newEntityJson.features[0].geometry.coordinates[0].push([
                    markersCoordinates[0][1],
                    markersCoordinates[0][0],
                ]);
            }
            newExtent = geojsonBbox(newEntityJson);
        }
        if (newExtent) {
            mapRef.flyToBounds(
                [
                    [newExtent[1], newExtent[0]],
                    [newExtent[3], newExtent[2]],
                ],
                {
                    ...(useClickMarker && markerResult !== '' ? { animate: true, duration: 0.25 } : { animate: false }),
                    paddingTopLeft: [30, 40],
                    paddingBottomRight: [30, 10],
                }
            );
        }
    };

    const addMarker = (e) => {
        if (!geoFileName) {
            mapRef?.flyTo(markersCoordinates[0], 7, { animate: false });
        }
    };

    const onClickFullScreen = () => {
        const newIsFullScreen = !isFullScreen;
        setIsFullScreen(newIsFullScreen);
        setMapHeight(newIsFullScreen ? '100vh' : initialMapHeight);
        setBoxCss(
            newIsFullScreen
                ? {
                      position: 'fixed',
                      top: 0,
                      left: 0,
                      width: '100%',
                      height: '100vh',
                      zIndex: 1000,
                      backgroundColor: 'black',
                  }
                : {}
        );
    };

    const onClickMap = (lat, lng) => {
        if (markerResult === '') {
            setMarkersCoordinates([[lat, lng]]);
            const buffed = buffer(entityJson.features[0], 2);
            const isMarkerRight = booleanContains(buffed.geometry, {
                type: 'Polygon',
                coordinates: [
                    [
                        [lng, lat],
                        [lng, lat],
                        [lng, lat],
                    ],
                ],
            });
            onMarkerSet(isMarkerRight);
        }
    };

    const MapEvents = () => {
        const map = useMapEvents({
            click(e) {
                onClickMap(e.latlng.lat, e.latlng.lng);
            },
        });
        return false;
    };

    return (
        <Box
            sx={{
                width: '100%',
                height: `${mapHeight}`,
                // maxHeight: '450px',
                position: 'relative',
                ...boxCss,
                '.leaflet-container': {
                    width: '100%',
                    height: `${mapHeight}`,
                    // maxHeight: '450px',
                },
                '.iconLightMode': {
                    filter: 'saturate(0)',
                },
                '.iconDarkMode': {
                    filter: 'invert(1)',
                },
                '.iconPrimary': {
                    filter: 'invert(45%) sepia(35%) saturate(7494%) hue-rotate(222deg) brightness(100%) contrast(102%)',
                },
                '.iconSecondary': {
                    filter: 'invert(16%) sepia(93%) saturate(1308%) hue-rotate(225deg) brightness(91%) contrast(98%)',
                },
                '.iconTertiary': {
                    filter: 'invert(74%) sepia(80%) saturate(3204%) hue-rotate(129deg) brightness(97%) contrast(103%)',
                },
                '.iconError': {
                    filter: 'invert(48%) sepia(42%) saturate(3029%) hue-rotate(330deg) brightness(104%) contrast(103%)',
                },
                '.leaflet-control-zoom.leaflet-bar.leaflet-control': {
                    borderWidth: 1,
                    borderRadius: '5px',
                },
                '.leaflet-touch .leaflet-bar a:first-of-type': {
                    borderTopLeftRadius: '5px',
                    borderTopRightRadius: '5px',
                },
                '.leaflet-touch .leaflet-bar a:last-of-type': {
                    borderBottomLeftRadius: '5px',
                    borderBottomRightRadius: '5px',
                },
                ...(isDarkMode && tileProviderKey !== TILE_SATELLITE
                    ? {
                          '.mainTiles .leaflet-tile-container img': {
                              filter: 'invert() hue-rotate(230deg) brightness(200%);',
                          },
                      }
                    : null),
                '.lineTiles .leaflet-tile-container img': {
                    filter: 'invert(45%) sepia(35%) saturate(7494%) hue-rotate(222deg) brightness(100%) contrast(102%)',
                },
                '.leaflet-control-attribution.leaflet-control': {
                    paddingRight: '10px',
                    ...(isDarkMode
                        ? {
                              backgroundColor: theme.palette.background.default,
                          }
                        : null),
                },
            }}>
            <MapContainer
                // ref={mapRef}
                id="mapSection"
                center={center}
                zoom={markers ? 7 : 1}
                scrollWheelZoom={true}
                maxBounds={[
                    [-80, -200],
                    [90, 200],
                ]}
                maxBoundsViscosity={1.0}
                whenReady={(e) => {
                    setMapRef(e.target);
                }}
                className={isFullScreen ? 'full-screen' : ''}>
                {useClickMarker && <MapEvents onClick={onClickMap} />}
                <TileLayer
                    url={tileProviders[tileProviderKey].url}
                    // attribution={tileProviders[tileProviderKey].attribution}
                    // noWrap
                    maxZoom={maxZoom ?? 16}
                    minZoom={2}
                    className="mainTiles"
                />
                {useBorderLines && linesJson && (
                    <GeoJSON key="lines" data={linesJson} style={{ weight: 2, color: theme.palette.neutral[600] }} />
                )}
                {(!useClickMarker || markerResult !== '') && (
                    <GeoJSON
                        // key={hash(geoFileName)}
                        key={hash}
                        data={entityJson}
                        style={setColor}
                        onEachFeature={handleFeature}
                    />
                )}
                {markersCoordinates &&
                    markersCoordinates?.map((m, i) =>
                        !!m ? (
                            <Marker
                                key={i}
                                eventHandlers={{
                                    add: addMarker,
                                }}
                                icon={icon}
                                position={m}></Marker>
                        ) : null
                    )}
            </MapContainer>
            {useFullScreen && (
                <IconButton
                    onClick={onClickFullScreen}
                    size="small"
                    sx={{
                        position: 'absolute',
                        right: 0,
                        top: 0,
                        zIndex: 400,
                        height: pxToRem(37),
                    }}>
                    {isFullScreen ? <CloseFullscreenIcon /> : <OpenInFullIcon />}
                </IconButton>
            )}
        </Box>
    );
};

export default Map;
